template <typename UnionPtrType>
ReadChunkResultPtr ReadChunkResult::Clone() const {
  switch (tag_) {
    case Tag::kData:
      return NewData(
          mojo::Clone(*data_.data));
    case Tag::kError:
      return NewError(
          mojo::Clone(*data_.error));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, ReadChunkResult>::value>::type*>
bool ReadChunkResult::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kData:
      return mojo::Equals(*(data_.data), *(other.data_.data));
    case Tag::kError:
      return mojo::Equals(*(data_.error), *(other.data_.error));
  }

  return false;
}
